import re, zlib, sys

p=sys.argv[1]
data=open(p,'rb').read()
objs={}; streams={}
for m in re.finditer(rb'(\d+)\s+(\d+)\s+obj\b', data):
    num=int(m.group(1)); start=m.end(); end=data.find(b'endobj', start)
    if end<0: end=len(data)
    body=data[start:end].strip(); objs[num]=body
    if b'stream' in body:
        s=body.find(b'stream'); e=body.rfind(b'endstream')
        raw=body[s+6:e]
        if raw.startswith(b'\r\n'): raw=raw[2:]
        elif raw.startswith(b'\n'): raw=raw[1:]
        try: streams[num]=zlib.decompress(raw)
        except Exception: pass
for num,dec in list(streams.items()):
    body=objs.get(num,b'')
    if b'/ObjStm' in body:
        mN=re.search(rb'/N\s+(\d+)', body); mF=re.search(rb'/First\s+(\d+)', body)
        if not mN or not mF: continue
        N=int(mN.group(1)); first=int(mF.group(1)); header=dec[:first].split()
        pairs=[(int(header[i]),int(header[i+1])) for i in range(0,len(header),2)]
        for i,(onum,off) in enumerate(pairs[:N]):
            end=first+pairs[i+1][1] if i+1<len(pairs) else len(dec)
            objs[onum]=dec[first+off:end].strip()

def get_stream(num):
    if num in streams: return streams[num]
    body=objs.get(num,b'')
    if b'stream' in body:
        s=body.find(b'stream'); e=body.rfind(b'endstream')
        raw=body[s+6:e]
        if raw.startswith(b'\r\n'): raw=raw[2:]
        elif raw.startswith(b'\n'): raw=raw[1:]
        try: return zlib.decompress(raw)
        except Exception: return None
    return None

def parse_cmap(num):
    data=get_stream(num)
    if not data: return {},1
    txt=data.decode('latin1')
    # codespace length
    m=re.search(r'begincodespacerange\s*<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>', txt)
    clen=len(m.group(1))//2 if m else 1
    cmap={}
    for block in re.findall(r'beginbfchar(.*?)endbfchar', txt, re.S):
        for src,dst in re.findall(r'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>', block):
            code=int(src,16); s=''
            for i in range(0,len(dst),4):
                s+=chr(int(dst[i:i+4],16))
            cmap[code]=s
    for block in re.findall(r'beginbfrange(.*?)endbfrange', txt, re.S):
        # handle array destinations
        for m in re.finditer(r'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>\s*(<([0-9A-Fa-f]+)>|\[(.*?)\])', block, re.S):
            lo=int(m.group(1),16); hi=int(m.group(2),16)
            if m.group(4):
                base=int(m.group(4),16)
                # dst is UTF-16BE hex; increment last code unit
                for i in range(hi-lo+1):
                    cmap[lo+i]=chr(base+i)
            else:
                arr=re.findall(r'<([0-9A-Fa-f]+)>', m.group(5))
                for i,a in enumerate(arr):
                    s=''
                    for j in range(0,len(a),4): s+=chr(int(a[j:j+4],16))
                    cmap[lo+i]=s
    return cmap,clen

def decode_str(hexstr, cmap, clen):
    b=bytes.fromhex(hexstr)
    out=[]
    for i in range(0,len(b)-clen+1,clen):
        code=int.from_bytes(b[i:i+clen],'big')
        out.append(cmap.get(code, chr(code) if code<0x110000 else '?'))
    return ''.join(out)

def font_info(fontnum):
    b=objs.get(fontnum,b'').decode('latin1')
    tu=re.search(r'/ToUnicode\s+(\d+)\s+0\s+R', b)
    subtype='Type3' if '/Subtype/Type3' in b else ('Type0' if '/Subtype/Type0' in b else '?')
    cmap,clen=parse_cmap(int(tu.group(1))) if tu else ({},1)
    return cmap,clen

# collect page content and resources
pages=[]
for num,b in sorted(objs.items()):
    bs=b.decode('latin1')
    if '/Type/Page' in bs and '/Type/Pages' not in bs:
        cm=re.search(r'/Contents\s+(\d+)\s+0\s+R', bs)
        if not cm: continue
        fonts={}
        fm=re.search(r'/Font\s*<<(.*?)>>', bs, re.S)
        if fm:
            for name,fr in re.findall(r'/(F\d+)\s+(\d+)\s+0\s+R', fm.group(1)):
                fonts[name]=int(fr)
        pages.append((num,int(cm.group(1)),fonts))

def extract_page(contentnum, fonts):
    content=get_stream(contentnum)
    if content is None: return ''
    txt=content.decode('latin1')
    font=None; cmap={}; clen=1
    out=[]; last_y=None; last_x=None; line_has=False
    # tokenize by lines; process Tf, Tm, Td, Tj, TJ, ', "
    for rawline in txt.splitlines():
        line=rawline.strip()
        if not line: continue
        # process tokens in order using a combined regex
        pos=0
        for m in re.finditer(r'/(F\d+)\s+([\d.]+)\s+Tf|([\d.-]+)\s+([\d.-]+)\s+Tm|([\d.-]+)\s+([\d.-]+)\s+Td|<([0-9A-Fa-f]+)>\s*Tj|\[(.*?)\]\s*TJ|\((.*?)\)\s*Tj', line):
            if m.group(1):
                name=m.group(1)
                if name in fonts:
                    font=name; cmap,clen=font_info(fonts[name])
            elif m.group(3) is not None:
                x=float(m.group(3)); y=float(m.group(4))
                if last_y is None or abs(y-last_y)>0.5:
                    if out and not out[-1].endswith('\n'): out.append('\n')
                elif last_x is not None and x>last_x+1:
                    # same line, new column
                    if out and not out[-1].endswith((' ','\n','\t')): out.append('\t')
                last_y=y; last_x=x; line_has=False
            elif m.group(5) is not None:
                # Td move; no output
                pass
            elif m.group(7) is not None:
                out.append(decode_str(m.group(7), cmap, clen))
            elif m.group(8) is not None:
                for h in re.findall(r'<([0-9A-Fa-f]+)>', m.group(8)):
                    out.append(decode_str(h,cmap,clen))
            elif m.group(9) is not None:
                out.append(m.group(9))
    s=''.join(out)
    # replace control char 1 with space
    s=s.replace('\x01',' ')
    s=re.sub(r'[ \t]+\n','\n',s)
    s=re.sub(r'\n{3,}','\n\n',s)
    return s.strip()

allout=[]
for pnum,cnum,fonts in pages:
    allout.append(f'===== PAGE {pnum} (content {cnum}) =====')
    allout.append(extract_page(cnum,fonts))
print('\n'.join(allout))
